{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP.",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance is placed in a public subnet, which may result in it being assigned a public IP. This increases the risk of unauthorized access."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "HIGH",
      "explanation": "The EC2 instance metadata service (IMDS) does not require the use of tokens, which can allow unauthorized access to sensitive metadata."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami           = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  availability_zone = \"us-east-2a\"\n  key_name      = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id = aws_subnet.levelupvpc-public-1.id\n\n  associate_public_ip_address = false\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Disabled public IP assignment for the EC2 instance to prevent exposure to the internet. Enabled HTTP token requirement for the instance metadata service (IMDS) to enhance security."
}
